import type { SidebarsConfig } from '@docusaurus/plugin-content-docs';
import * as fs from 'fs';
import * as path from 'path';

// Import generated API sidebars
// These are auto-generated by docusaurus-plugin-openapi-docs

// Strip `link` from subcategories so they expand/collapse instead of navigating to a card page
function stripSubcategoryLinks(items: any[]): any[] {
  return items.map(item => {
    if (item.type === 'category') {
      const { link, ...rest } = item;
      return { ...rest, items: stripSubcategoryLinks(rest.items || []) };
    }
    return item;
  });
}

// Helper to relabel the intro page as "Overview" and keep it as the first child item
// Clicking the category expands/collapses; the overview is accessible as a regular item inside
function prepareCategoryItems(sidebarItems: any[]) {
  const introItem = sidebarItems.find(item => item.type === 'doc' && item.id?.endsWith('-api'));
  const otherItems = sidebarItems.filter(item => !(item.type === 'doc' && item.id?.endsWith('-api')));

  const items = introItem
    ? [{ ...introItem, label: 'Overview' }, ...stripSubcategoryLinks(otherItems)]
    : stripSubcategoryLinks(otherItems);

  return { items };
}

// Dynamically discover all API categories from docs/api/ subdirectories
// Each category must have a sidebar.ts and an info.mdx file
function discoverApiCategories() {
  const apiDocsDir = path.join(__dirname, 'docs', 'api');
  const categories: Array<{ dirName: string; label: string }> = [];

  if (!fs.existsSync(apiDocsDir)) {
    return [];
  }

  const entries = fs.readdirSync(apiDocsDir, { withFileTypes: true });

  for (const entry of entries) {
    if (!entry.isDirectory()) continue;

    const sidebarPath = path.join(apiDocsDir, entry.name, 'sidebar.ts');
    if (!fs.existsSync(sidebarPath)) continue;

    // Extract label from the info.mdx title frontmatter
    let label = entry.name
      .replace(/---/g, ' - ')
      .replace(/-/g, ' ')
      .replace(/\b\w/g, c => c.toUpperCase());

    // Look for the info.mdx file to get the proper title
    const infoFiles = fs.readdirSync(path.join(apiDocsDir, entry.name))
      .filter(f => f.endsWith('.info.mdx'));

    if (infoFiles.length > 0) {
      const infoContent = fs.readFileSync(
        path.join(apiDocsDir, entry.name, infoFiles[0]),
        'utf-8'
      );
      const titleMatch = infoContent.match(/^title:\s*"(.+?)"/m);
      if (titleMatch) {
        // Strip trailing " API" from the title for the sidebar label
        label = titleMatch[1].replace(/\s+API$/, '');
      }
    }

    categories.push({ dirName: entry.name, label });
  }

  // Sort alphabetically by label
  categories.sort((a, b) => a.label.localeCompare(b.label));

  return categories.map(({ dirName, label }) => ({
    type: 'category' as const,
    label,
    collapsed: true,
    ...prepareCategoryItems(require(`./docs/api/${dirName}/sidebar.ts`).default),
  }));
}

const sidebars: SidebarsConfig = {
  // Getting started and guides sidebar
  guideSidebar: [
    'intro',
    {
      type: 'category',
      label: 'Getting Started',
      collapsed: false,
      items: [
        'guides/authentication',
        'guides/popular-apis',
        'guides/products-sites-workspaces',
      ],
    },
    {
      type: 'category',
      label: 'Core Concepts',
      items: [
        'guides/pagination',
        'guides/filtering',
        'guides/error-handling',
      ],
    },
    {
      type: 'category',
      label: 'Working with Data',
      items: [
        'guides/working-with-tickets',
        'guides/ticket-activities',
        'guides/working-with-assets',
      ],
    },
    {
      type: 'category',
      label: 'Integration',
      items: [
        'guides/webhooks',
        'guides/support',
      ],
    },
  ],

  // API Reference sidebar - dynamically discovers all generated API categories
  // Scans docs/api/ for subdirectories with sidebar.ts, reads labels from info.mdx titles
  // Categories are sorted alphabetically
  apiSidebar: [
    {
      type: 'doc',
      id: 'api/index',
      label: 'API Overview',
    },
    ...discoverApiCategories(),
  ],
};

export default sidebars;
